Translate("deDE", "westfall", {
	title = "Westfall",
	aliases = { "die Ebenen von Westfall" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Westfall ist ein Land weiter goldener Ebenen zwischen dem {link:elwynn-forest}Wald von Elwynn{/link} und dem Großen Meer. Über Generationen füllten seine Höfe die Kornspeicher des {link:kingdom-of-stormwind}Königreichs Stormwind{/link}, und die Leute der {link:capital-city}Hauptstadt{/link} nannten es ihre Kornkammer. Nun liegen die Felder brach. Windmühlen drehen sich über leeren Scheunen, seltsame Maschinen stapfen durch die Furchen, und Männer mit roten Masken beherrschen die Straßen. Die meisten Bauern sind fort. Die Gebliebenen haben gelernt, dass keine Armee kommen wird und dass sie ihre Heimat selbst verteidigen müssen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet das Jahr, in dem die ersten Bauern die Ebenen westlich von {link:stormwind-city}Stormwind{/link} pflügten. Bekannt ist, dass das Land an mehr als nur Korn reich war. Unter seinen Hügeln lagen Minen und Steinbrüche, die die Schmieden der {link:capital-city}Hauptstadt{/link} versorgten, und die größte von ihnen, unter dem Dorf {link:moonbrook}Moonbrook{/link}, war einst die reichste Goldgrube aller Menschenlande. Die Küste gab den Dörfern Fisch und den Schiffen Gefahr, und auf den südlichen Felsen wurde ein Leuchtturm errichtet, um die Seeleute an ihnen vorbeizuführen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Westfall gehört der {link:defias-brotherhood}Bruderschaft der Defias{/link} in allem außer dem Namen. Die Bruderschaft hält {link:moonbrook}Moonbrook{/link}, die Minen und die südlichen Hügel. Sie vertrieb die Bauern aus ihren Häusern, mal durch Drohung und mal durch Feuer, und bewirtschaftet das Land nun für ihre eigenen Zwecke. {link:riverpaw-gnolls}Flusspfoten-Gnolle{/link} und {link:kobolds}Kobolde{/link} schuften auf ihren Befehl in den Minen. {link:stormwind-city}Stormwind{/link} hat keine Soldaten geschickt. Seine Armee steht weit fort, und der Hof des Regenten hat die Bitten Westfalls mit Schweigen beantwortet. Auf der {link:sentinel-hill}Späherkuppe{/link} hat ein Veteran namens {link:gryan-stoutmantle}Gryan Stoutmantle{/link} die Volksmiliz aus Bauern aufgestellt, die sich weigerten zu gehen. Sie sind wenige, doch sie sind das einzige Gesetz in Westfall.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Bauern von Westfall.{/b} Eine Handvoll Familien, wie die Saldeans, halten ihr Land gegen jede Gefahr. Andere, wie die Furlbrows, haben gepackt, was sie konnten, und sich der Stadt zugewandt.
• {b}Die Volksmiliz.{/b} Ehemalige Bauern und heimgekehrte Soldaten unter {link:gryan-stoutmantle}Gryan Stoutmantle{/link}, die geschworen haben, die Ebenen im Namen des {link:holy-light}Heiligen Lichts{/link} zu verteidigen.
• {b}Die {link:defias-brotherhood}Bruderschaft der Defias{/link}.{/b} Diebe, Schmuggler und Plünderer mit roten Halstüchern. Farbe und Stoff des Halstuchs zeigen den Rang eines Mitglieds.
• {b}Die {link:riverpaw-gnolls}Flusspfoten-Gnolle{/link}.{/b} Sie überfallen die Felder und graben im Goldküstensteinbruch für die Bruderschaft.
• {b}Murlocs.{/b} Die Stämme der {link:murlocs}Murlocs{/link} wimmeln entlang der gesamten Küste.
• {b}Die {link:harvest-golems}Erntegolems{/link}.{/b} Maschinen, die gebaut wurden, um die Felder zu bestellen, vertreiben nun jeden, der ihnen nahe kommt.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Jahre des Überflusses.{/b} Korn und Gold machten Westfall zu einer der Säulen des Königreichs.
• {b}Der Erste Krieg.{/b} Als die {link:horde}Horde{/link} im {link:first-war}Ersten Krieg{/link} {link:stormwind-city}Stormwind{/link} schleifte, wurde die große Goldmine unter {link:moonbrook}Moonbrook{/link} aufgegeben. Sie erhielt den Namen {link:the-deadmines}Todesminen{/link}.
• {b}Der Verrat an den Steinmetzen.{/b} Nach dem {link:second-war}Zweiten Krieg{/link} baute die {link:stonemasons-guild}Steinmetzgilde{/link} die {link:capital-city}Hauptstadt{/link} wieder auf und wurde vom {link:house-of-nobles}Adelshaus{/link} um ihren Lohn betrogen. Aus der Stadt vertrieben, zogen die Steinmetze unter {link:edwin-vancleef}Edwin VanCleef{/link} nach Westen und machten Westfall zu ihrem Land.
• {b}Die Preisgabe.{/b} Ein Hof nach dem anderen fiel. Stormwind antwortete nicht. {link:gryan-stoutmantle}Gryan Stoutmantle{/link}, heimgekehrt aus dem Untergang von {link:lordaeron}Lordaeron{/link}, begann jene zu sammeln, die bleiben und kämpfen wollten.]=],
		},
		{
			title = "Überlieferungen der Ebenen",
			text = [=[• Die Bruderschaft stiehlt nicht nur Höfe. Sie stiehlt auch deren Urkunden, und man sagt, ihre Fälscher könnten eine gestohlene Urkunde einem neuen Herrn dienen lassen.
• Entlang von {link:longshore}Longshore{/link} liegen die Wracks vieler Schiffe. Die Seeleute des Großen Meeres erzählen noch von einem ertrunkenen Kapitän, der eine Spur von Hinweisen auf seinen versteckten Schatz hinterließ.
• Ein Geist hütet die Flamme des Leuchtturms von Westfall. Er starb auf den Felsen darunter, und er will keinen anderen Seemann dasselbe Schicksal erleiden lassen.
• Die Bauern sagen, die Felder von Westfall seien krank, und die Krankheit komme von unter der Erde.]=],
		},
	},
})

Translate("deDE", "sentinel-hill", {
	title = "Späherkuppe",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Späherkuppe erhebt sich inmitten von {link:westfall}Westfall{/link}, gleich abseits der großen Straße. Auf ihrem Scheitel steht ein steinerner Wachturm, und um ihn herum hat sich zum Schutz ein kleines Dorf gesammelt: ein Gasthaus, die Stände der Familie MacGregor und die Posten der Miliz. Dies ist das Hauptquartier der Volksmiliz. Von der Spitze des Turms beobachten {link:gryan-stoutmantle}Gryan Stoutmantle{/link} und seine Offiziere die Ebenen und senden ihre Späher aus. Es ist der letzte Ort in Westfall, an dem das Gesetz Stormwinds noch laut ausgesprochen wird, auch wenn {link:stormwind-city}Stormwind{/link} selbst nichts schickt, um es durchzusetzen.]=],
		},
	},
})

Translate("deDE", "moonbrook", {
	title = "Moonbrook",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Moonbrook war einst ein wohlhabendes Dorf im Süden von {link:westfall}Westfall{/link}. Seine Leute sind fort. Die {link:defias-brotherhood}Bruderschaft der Defias{/link} nahm die Stadt ein und machte sie zum Herzen ihrer Macht, und ihre leeren Häuser beherbergen nun Diebe und deren Hauptleute. Nur ein Händler treibt in Moonbrook offen Handel, ein Kaufmann der Defias, der an jeden mit Münzen verkauft und keine Fragen stellt. Unter der Stadt liegt die alte Goldmine, die der Krieg zurückließ: die {link:the-deadmines}Todesminen{/link}. Die Steinmetze {link:edwin-vancleef}Edwin{/link} VanCleefs bewachen ihren Eingang, denn was sie in der Tiefe bauen, ist das größte Geheimnis der Bruderschaft.]=],
		},
	},
})

Translate("deDE", "jangolode-mine", {
	title = "Der Jangoschacht",
	aliases = { "Jangoschacht" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Jangoschacht liegt im Nordwesten von {link:westfall}Westfall{/link}, in den Hügeln oberhalb des Hofs der Furlbrows. Er war eine der Minen, die Erz nach {link:stormwind-city}Stormwind{/link} lieferten. Nun halten ihn die {link:defias-brotherhood}Defias{/link}, und ihre Fallensteller streifen durch das Land um seinen Eingang. Drinnen hat die Bruderschaft {link:kobolds}Kobolde{/link} für sich graben lassen. Sie arbeiten unter einem Meistergräber ihrer eigenen Art. Manche, die die Krankheit der Ebenen erforscht haben, suchten ihre Quelle zuerst hier, im Abraum der Mine.]=],
		},
	},
})

Translate("deDE", "gold-coast-quarry", {
	title = "Der Goldküstensteinbruch",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Goldküstensteinbruch liegt am Westrand von {link:westfall}Westfall{/link}, wo die Ebenen zum Meer hin abfallen. Er gab dem Königreich sowohl Stein als auch Gold. Nun halten ihn Plünderer der {link:defias-brotherhood}Defias{/link}, und die {link:riverpaw-gnolls}Flusspfoten-Gnolle{/link} schuften in seinen Gruben unter der Peitsche ihrer eigenen Zuchtmeister. Die {link:gnolls}Gnolle{/link} graben nicht für sich selbst. Sie graben für die Bruderschaft, deren Verbündete sie überall auf den Ebenen geworden sind. Die Plünderer aus dem Steinbruch zu vertreiben, ist eine der Prüfungen, die die Volksmiliz jenen auferlegt, die sich ihren Reihen anschließen wollen.]=],
		},
	},
})

Translate("deDE", "alexston-farmstead", {
	title = "Alexstons Bauernhof",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Alexstons Bauernhof ist einer der alten Familienhöfe im mittleren {link:westfall}Westfall{/link}. Seine Familie ist geflohen, und seine Felder sind den {link:harvest-golems}Erntegolems{/link} anheimgefallen, die noch immer die Reihen abschreiten, als warte eine Ernte darauf, eingebracht zu werden. Banden von Plünderern und Räubern der {link:defias-brotherhood}Defias{/link} ziehen durch den Hof, wenn sie zwischen dem Steinbruch und {link:moonbrook}Moonbrook{/link} unterwegs sind, und nehmen mit, was die letzten Besitzer zurückgelassen haben. Sie vom Hof zu vertreiben, gehört zu den ersten Aufgaben, die die Volksmiliz jenen stellt, die ihr beitreten wollen.]=],
		},
	},
})

Translate("deDE", "saldeans-farm", {
	title = "Saldeans Farm",
	aliases = { "Hof der Saldeans" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Saldeans Farm liegt nördlich der {link:sentinel-hill}Späherkuppe{/link}, gleich hinter einer Gabelung der großen Straße. Sie ist einer der wenigen Höfe in {link:westfall}Westfall{/link}, deren Besitzer nicht geflohen sind. {link:farmer-saldean}Bauer Saldean{/link} und seine Frau {link:salma-saldean}Salma{/link} haben ihre Nachbarn einen nach dem anderen gehen sehen, und doch halten sie ihr Haus, ihre Küche und ihren Wagen. Beinahe wäre der Wagen den Weg von allem anderen gegangen, als ein Dieb der {link:defias-brotherhood}Defias{/link} ihn zu stehlen versuchte. Er wurde gefasst, und um sein Leben zu retten, bot er der Miliz das Eine an, was sie sich am meisten wünschte: den Weg zum Versteck der Bruderschaft.]=],
		},
	},
})

Translate("deDE", "furlbrows-pumpkin-farm", {
	title = "Furlbrows Kürbishof",
	aliases = { "Hof der Furlbrows" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Furlbrows Kürbishof liegt im Norden von {link:westfall}Westfall{/link}, nahe dem {link:jangolode-mine}Jangoschacht{/link}. Er gehörte Theodore und {link:verna-furlbrow}Verna Furlbrow{/link} bis zu der Nacht, in der sich ihre Felder mit Dieben füllten. Die Furlbrows flohen so eilig, dass Theodore seinen wertvollsten Besitz, eine Taschenuhr, im Kleiderschrank des Bauernhauses zurückließ. Die {link:defias-brotherhood}Defias{/link} nahmen den Hof und auch die Urkunde dazu. Nun verrotten Kürbisse auf dem Feld, und {link:harvest-golems}Erntegolems{/link} bewachen eine Ernte, die niemand je einbringen wird.]=],
		},
	},
})

Translate("deDE", "the-dagger-hills", {
	title = "Die Dolchhügel",
	aliases = { "Dolchhügel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Dolchhügel sind das zerklüftete Hochland im Süden von {link:westfall}Westfall{/link}, hinter {link:moonbrook}Moonbrook{/link} und über dem Meer. Hier schlagen die härtesten Kämpfer der Bruderschaft ihre Lager auf: Wegelagerer, die die Straßen berauben, Pfadpirscher, die jeden Pfad kennen, und Schläger, die Streit mit den Fäusten beilegen. Die Miliz glaubt, dass Räuber der {link:defias-brotherhood}Defias{/link}, die ihren Patrouillen entkommen, in diesen Hügeln untertauchen, um ihren nächsten Angriff zu planen. Auf der anderen Seite der Hügel, nahe am Wasser, führt ein verborgener Weg aus den Tiefen der {link:the-deadmines}Todesminen{/link} heraus. Nur wer die Minen durchquert hat, weiß, wo er liegt.]=],
		},
	},
})

Translate("deDE", "westfall-lighthouse", {
	title = "Der Leuchtturm von Westfall",
	aliases = { "der Leuchtturm" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Leuchtturm von Westfall steht auf der südwestlichen Spitze des Landes, über Felsen, an denen schon viele Schiffe zerschellt sind. Sein Wärter und dessen Familie hüteten einst die Flamme. Zweimal kamen die {link:murlocs}Murlocs{/link} der Küste über sie, angeführt von einem großen Murloc namens {link:old-murk-eye}Old Murk-Eye{/link}. Beim ersten Mal floh die Familie, und das Licht erlosch, und in jener Nacht starb ein Schiffskapitän auf den Felsen. Beim zweiten Mal entkam die Familie nicht. Das Licht brennt noch immer, denn der ertrunkene Kapitän lässt es nicht erlöschen.]=],
		},
	},
})

Translate("deDE", "the-dead-acre", {
	title = "Der Todesacker",
	aliases = { "Todesacker" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Todesacker liegt im Südosten von {link:westfall}Westfall{/link}, nahe der Brücke, die in den {link:duskwood}Dämmerwald{/link} führt. Er war einst ein Hof wie die anderen. Als die Bruderschaft kam, wurden Haus und Felder in Brand gesteckt, und nur geschwärzte Ruinen sind geblieben. Die {link:harvest-golems}Erntemaschinen{/link}, die durch seine rauchenden Reihen stapfen, sind die gefährlichsten in Westfall, große Mäher, denen sich kein Bauer zu nähern wagte. Wegelagerer der {link:defias-brotherhood}Defias{/link} halten zwischen den verbrannten Gebäuden Wache. Von der Familie, die einst hier lebte, ist keine Aufzeichnung geblieben.]=],
		},
	},
})

Translate("deDE", "the-molsen-farm", {
	title = "Molsens Hof",
	aliases = { "Hof der Molsens" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Molsens Hof ist eine der verlassenen Heimstätten im nördlichen {link:westfall}Westfall{/link}. Seine Familie ist fort, und Fallensteller der {link:defias-brotherhood}Defias{/link} wurden auf seinen Feldern gesehen. Der Brunnen des Hofs gibt noch Wasser, doch das Wasser ist nicht mehr rein. Wer es geprüft hat, findet darin Metalle, die in einen Schmelzofen gehören und nicht in den Eimer eines Bauern. Was auch immer den Boden von Westfall vergiftet, hat den Brunnen der Molsens erreicht, und es breitet sich von anderswo durch die Erde aus.]=],
		},
	},
})

Translate("deDE", "the-jansen-stead", {
	title = "Jansens Siedlung",
	aliases = { "Siedlung der Jansens" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Jansens Siedlung ist der nördlichste Hof von {link:westfall}Westfall{/link}, nahe der Brücke, die nach {link:elwynn-forest}Elwynn{/link} hinüberführt. Es ist der erste Hof, den ein Reisender aus {link:stormwind-city}Stormwind{/link} sieht, und das erste Zeichen dafür, wie tief das Land gefallen ist. Seine Besitzer wurden vertrieben wie so viele andere, und {link:harvest-golems}Erntegolems{/link} und {link:defias-brotherhood}Defias{/link} halten die Felder. Nahe der Straße warten die Furlbrows neben ihrem zerbrochenen Wagen auf die Gelegenheit, Westfall für immer zu verlassen. Auch im Brunnen der Siedlung hat man, wie in dem von {link:the-molsen-farm}Molsens Hof{/link}, Gift gefunden.]=],
		},
	},
})

Translate("deDE", "longshore", {
	title = "Longshore",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Longshore ist die lange Westküste von {link:westfall}Westfall{/link}, ein Streifen aus Sand und Fels am Großen Meer. Die Wracks vieler Schiffe liegen dort, halb im Sand begraben. Die Küste gehört den {link:murlocs}Murlocs{/link}. Ihre Dörfer drängen sich an den Stränden, und ihre Plünderer greifen jeden an, der am Ufer entlanggeht. Der schlimmste von ihnen ist {link:old-murk-eye}Old Murk-Eye{/link}, der die Murlocs einst gegen den Leuchtturm von Westfall führte. Zwischen den Wracks markiert ein rostiger Anker die Stelle, an der der ertrunkene Kapitän Sanders den ersten Hinweis auf seinen Schatz hinterlassen haben soll.]=],
		},
	},
})

Translate("deDE", "gryan-stoutmantle", {
	title = "Gryan Stoutmantle",
	subtitle = "Anführer der Volksmiliz",
	found = "Die Spitze des Turms auf der Späherkuppe",
	hint = [=[Steigt auf den Turm der Späherkuppe und sprecht mit dem Anführer der Miliz.]=],
	allegiance = "Die Volksmiliz",
	aliases = { "Stoutmantle", "Lord Stoutmantle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gryan Stoutmantle führt die Volksmiliz vom Wachturm auf der {link:sentinel-hill}Späherkuppe{/link} aus. Er kehrte aus den verseuchten Landen von {link:lordaeron}Lordaeron{/link} heim und fand seine Heimat von Dieben überrannt und von ihrem König vergessen. Er wartete nicht auf Hilfe. Er sammelte die Bauern, die nicht gehen wollten, gab ihnen Waffen und ließ sie schwören, {link:westfall}Westfall{/link} im Namen des {link:holy-light}Heiligen Lichts{/link} zu verteidigen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Stoutmantle ist die Antwort einfacher Leute auf ein Königreich, das sie im Stich gelassen hat. Es ist seine Miliz und nicht die Armee von {link:stormwind-city}Stormwind{/link}, die die Wahrheit über die {link:defias-brotherhood}Bruderschaft der Defias{/link} aufdeckt und ihren Herrn bis in seinen Unterschlupf jagt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er gründete die Volksmiliz und nimmt ihre Mitglieder selbst auf.
• Er schickt seine Späher durch ganz {link:westfall}Westfall{/link} hinter den {link:defias-brotherhood}Defias{/link} her.
• Er lehnte ein Hilfegesuch von {link:magistrate-solomon}Magistrat Solomon{/link} aus {link:lakeshire}Seenhain{/link} ab, denn er hatte keine Männer zu entbehren.
• Er führte die Jagd auf {link:edwin-vancleef}Edwin VanCleef{/link} an.]=],
		},
	},
	chapters = {
		{
			title = "Die Miliz der Späherkuppe",
			hint = "Beweist Euch gegen die Defias von Westfall.",
			text = [=[Die Miliz nimmt niemanden auf bloßes Wort hin auf. Ihre Anwärter müssen die {link:defias-brotherhood}Defias{/link} zuerst von den Höfen vertreiben, dann aus dem Steinbruch und zuletzt aus den südlichen Hügeln. Erst dann nimmt Stoutmantle sie auf und spricht dabei vom Untergang, den er in {link:lordaeron}Lordaeron{/link} zurückließ, und von der Hoffnung, die er für {link:westfall}Westfall{/link} noch hegt.]=],
		},
		{
			title = "Ein Versprecher",
			hint = "Findet heraus, wer die Bruderschaft anführt.",
			text = [=[Stoutmantle wandte sich an einen alten Bekannten in {link:lakeshire}Seenhain{/link}, einen Schurken, der ihm einen Gefallen schuldete. Die Notiz des Schurken berichtete, dass die {link:defias-brotherhood}Defias{/link} mit Gnollen, Kobolden und Goblins zusammenarbeiteten. Sie verriet auch ein Wort, das Stoutmantle nicht vergessen konnte: Steinmetze.]=],
		},
		{
			title = "Ein Name, den er kannte",
			hint = "Tragt die Frage nach den Steinmetzen nach Stormwind.",
			text = [=[Die Antwort von {link:master-mathias-shaw}Mathias Shaw{/link} von {link:si-7}SI:7{/link} nannte den Meister der alten {link:stonemasons-guild}Steinmetzgilde{/link}: {link:edwin-vancleef}Edwin VanCleef{/link}. Stoutmantle kannte den Namen. Es fiel ihm schwer zu glauben, dass ein so begabter Mann zu einem Fürsten der Diebe geworden war, und er verlangte einen Beweis.]=],
		},
		{
			title = "Das Haupt der Bruderschaft",
			hint = "Bringt die Jagd auf den Anführer der Defias zu Ende.",
			text = [=[Als das Versteck gefunden war, gab Stoutmantle den Befehl, den er am wenigsten geben wollte. {link:edwin-vancleef}VanCleef{/link} sollte sterben. Als der Beweis zur {link:sentinel-hill}Späherkuppe{/link} zurückkam, sprach er davon als dem Anfang vom Ende der Bruderschaft und von einem Tag, an dem der Frieden in die Ebenen zurückkehren könnte.]=],
		},
