	aliases = { "Defias-Verräter" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Verräter der Defias ist ein Dieb der Bruderschaft, der gefasst wurde, als er den Wagen der Saldeans stehlen wollte. Um seinen Hals zu retten, schloss er einen Handel mit der Miliz: Er würde sie zum geheimen Versteck der Bruderschaft führen. Er weiß, was ihn das macht. Seine alten Kameraden wollen seinen Kopf, und er wird die Straße nicht ohne jemanden gehen, der ihm den Rücken deckt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Durch seinen Verrat verliert die Bruderschaft ihren größten Schutz, die Geheimhaltung.]=],
		},
		{
			title = "Taten",
			text = [=[• Er versuchte, den Wagen von {link:farmer-saldean}Bauer Saldean{/link} zu stehlen, und wurde gefangen genommen.
• Er führte die Streiter der Miliz über die südlichen Straßen zum Versteck unter {link:moonbrook}Moonbrook{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Der Weg nach Moonbrook",
			hint = "Beschützt den Verräter auf dem Weg zum Versteck der Defias.",
			text = [=[Der Verräter wusste, dass seine alten Kameraden versuchen würden, ihn zu töten, wenn sie ihn mit der Miliz sähen, und so kam es. Er erreichte {link:moonbrook}Moonbrook{/link} lebend und zeigte, wo {link:edwin-vancleef}VanCleef{/link} und seine Steinmetze sich versteckten.]=],
		},
	},
	mentions = {
		{ text = "Die {link:defias-brotherhood}Bruderschaft der Defias{/link}" },
		{ text = "Die {link:defias-brotherhood}Bruderschaft der Defias{/link}" },
	},
	bonds = {
