		{ id = "farmer-saldean", name = "Bauer Saldean", note = "der Mann, den er zu berauben versuchte" },
		{ id = "edwin-vancleef", name = "Edwin VanCleef", note = "der Herr, den er verriet" },
	},
})

Translate("deDE", "farmer-saldean", {
