	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Theodore Furlbrow besaß den Kürbishof nahe dem {link:jangolode-mine}Jangoschacht{/link}, bis zu der Nacht, in der sich seine Felder mit Halunken füllten. Er und seine Frau {link:verna-furlbrow}Verna{/link} flohen in Eile, und nun sitzen sie neben einem zerbrochenen Wagen an der Straße aus {link:westfall}Westfall{/link} hinaus. Er rechnet nicht damit zurückzukehren. Dennoch hätte er gern seine Urkunde zurück, falls das Land je wieder für ehrliche Leute taugen sollte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die Furlbrows sind das Gesicht der Familien, die aufgegeben haben. Ihr Hof, ihre Urkunde und sogar ihre Andenken fielen in die Hände der {link:defias-brotherhood}Defias{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er floh mit seiner Frau in der Nacht, als die Diebe kamen, von seinem Hof.
• Er sucht die Taschenuhr, die Vernas Vater ihm an ihrem Hochzeitstag schenkte.]=],
		},
	},
	chapters = {
		{
			title = "Die gestohlene Urkunde",
			hint = "Bringt den Furlbrows zurück, was die Diebe ihnen nahmen.",
			text = [=[Die Urkunde des Hofs der Furlbrows tauchte in den Händen der {link:defias-brotherhood}Defias{/link} auf, mit einer Notiz auf der Rückseite. Die Diebe hatten Furlbrow dazu gedrängt, sie herauszugeben, und glaubten, sie könne als Vorlage für ihre eigenen gefälschten Urkunden dienen. Ihrem Besitzer zurückgegeben, wurde sie zu einem Versprechen: Sollte {link:westfall}Westfall{/link} je sicher werden, können die Furlbrows ihr Land beanspruchen.]=],
		},
	},
	mentions = {
		{ text = "Das vergessene Erbstück" },
		{
			text = [=[Meldet Euch bei {link:gryan-stoutmantle}Gryan Stoutmantle{/link}]=],
		},
	},
	bonds = {
