		{ text = "Die Bedrohung von der Küste" },
		{ text = "Die Küste ist nicht sicher" },
	},
	bonds = {
		{ id = "old-murk-eye", name = "Old Murk-Eye", note = "der Murloc, der die Überfälle anführte" },
	},
})

