		{
			title = "Zusammenfassung",
			text = [=[Agentin Kearnen dient {link:si-7}SI:7{/link}, den Spionen von {link:stormwind-city}Stormwind{/link}. Seit Wochen beobachtet sie einen verlassenen Wachturm südöstlich der {link:sentinel-hill}Späherkuppe{/link}, den die {link:defias-brotherhood}Defias{/link} zu einem Stützpunkt für Waren gemacht haben, die auf der Straße ins {link:redridge-mountains}Rotkammgebirge{/link} geschmuggelt werden. Was sie gesehen hat, beunruhigt sie. Eine Lieferung kam aus dem {link:duskwood}Dämmerwald{/link} mit einer Truhe, und mit ihr kamen Wachen, die keine {link:humans}Menschen{/link} sind.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kearnens Wache deckt einen finstereren Handel in den Händen der Bruderschaft auf. Die Truhe im Turm gehört dem {link:defias-brotherhood}Defias{/link} Klaven Mortwake, und ihre Geheimnisse führen weit nach Süden zu den Trollen des {link:stranglethorn-vale}Schlingendorntals{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie führt ein Tagebuch über alles, was sie am Turm sieht.
• Sie wartet darauf, dass {link:si-7}SI:7{/link} einen weiteren Agenten schickt.]=],
		},
	},
	mentions = {
		{ text = "Mathias und die {link:defias-brotherhood}Defias{/link}" },
		{ text = "Klavens Turm" },
	},
	bonds = {
		{ id = "master-mathias-shaw", name = "Meister Mathias Shaw", note = "ihr Meister bei SI:7" },
	},
})

Translate("deDE", "alba-fairmoon", {
