			text = [=[Alba Fairmoon ist eine {link:night-elves}Nachtelfe{/link} aus {link:darnassus}Darnassus{/link}, die nach {link:westfall}Westfall{/link} gekommen ist, um herauszufinden, warum sein Land stirbt. Sie begann mit dem Wasser, prüfte die Brunnen der Höfe und fand sie voller giftiger Metalle. Sie folgte dem Gift durch die Minen und den Steinbruch und schließlich bis nach {link:moonbrook}Moonbrook{/link}, wo sie Zeichen großer Werke unter der Erde fand.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Alba fürchtet, dass in {link:westfall}Westfall{/link} jahrzehntelang kein Getreide mehr wachsen wird, wenn das Gift nicht aufgehalten wird, und dass {link:stormwind-city}Stormwind{/link} eine Hungersnot droht.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie prüfte die Brunnen von {link:the-jansen-stead}Jansens Siedlung{/link} und {link:the-molsen-farm}Molsens Hof{/link}.
• Sie verfolgte das Gift bis zu einer Schmiede, die in den {link:the-deadmines}Todesminen{/link} verborgen ist.]=],
		},
	},
	chapters = {
		{
			title = "Die Schmiede in der Tiefe",
			hint = "Folgt dem Gift der Brunnen bis zu seiner Quelle.",
			text = [=[Mit Sprengstoff aus {link:stormwind-city}Stormwind{/link} wurde die Schmiede in den {link:the-deadmines}Todesminen{/link} zerstört. Alba wartete in den Hügeln hinter {link:moonbrook}Moonbrook{/link}, um zu sehen, dass es vollbracht wurde. Danach sprach sie voller Kummer von einem Königreich, dem seine Kriege mehr wert zu sein schienen als das Auskommen seines eigenen Volkes.]=],
