		{ text = "Spionage in {link:moonbrook}Moonbrook{/link}" },
		{ text = "Explosive Beratung" },
		{ text = "Zerstörung in den {link:the-deadmines}Todesminen{/link}" },
	},
	bonds = {
		{ id = "gryan-stoutmantle", name = "Gryan Stoutmantle", note = "verteidigt das Land, das sie erforscht" },
	},
})

Translate("deDE", "ozwin-ironsprocket", {
	title = "Ozwin Ironsprocket",
	subtitle = "Tüftler aus Gnomeregan",
