	hint = [=[Sucht im Stall von Saldeans Farm nach einem versteckten Gnom.]=],
	allegiance = "Gnomeregangnome",
	aliases = { "Ozwin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ozwin Ironsprocket ist ein {link:gnomes}Gnom{/link}, der den ganzen Weg aus {link:ironforge}Ironforge{/link} kam, als er von den {link:harvest-golems}Erntegolems{/link} hörte, die in {link:westfall}Westfall{/link} außer Kontrolle geraten waren. Er wollte sie neu kalibrieren. Die Maschinen erwiesen sich als weit angriffslustiger, als seine Berechnungen vorsahen, und jagten ihn in den Stall von {link:saldeans-farm}Saldeans Farm{/link}, wo er sich seitdem versteckt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ozwin ist der Einzige in {link:westfall}Westfall{/link}, der versucht, die {link:harvest-golems}Erntegolems{/link} zu verstehen, statt sie bloß zu zerstören.]=],
