	},
	mentions = {
		{ text = "Die Ernter ernten" },
		{ text = "Die Ernter ernten" },
	},
	bonds = {
		{ id = "farmer-saldean", name = "Bauer Saldean", note = "gewährt ihm Unterschlupf in seinem Stall" },
