})

Translate("deDE", "harvest-golems", {
	title = "Erntegolems",
	aliases = { "Erntegolems", "Erntegolem", "Erntewächter", "Erntemaschinen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Erntegolems sind große Maschinen aus Eisen, die gebaut wurden, um die Felder von {link:westfall}Westfall{/link} zu bestellen. Sie wurden geschaffen, um zu ernten, zu säen und über die Feldfrüchte zu wachen. Nun stapfen sie ohne Herrn über die verlassenen Höfe und vertreiben jeden, der ihnen nahe kommt, als wären die Bauern selbst Schädlinge, die aus den Reihen zu entfernen sind.]=],
		},
		{
			title = "Arten",
			text = [=[• {b}Rostige Erntegolems{/b} und {b}Erntegolems{/b} sind die kleinsten und schwächsten von ihnen.
• {b}Erntewächter{/b} bewachen die Felder, wie ihr Name sagt.
• {b}Erntemäher{/b} sind die größten und gefährlichsten. Sie streifen über die verbrannten Felder des Todesackers.
• {b}Der Foe Reaper 4000{/b} ist eine einzelne Maschine, weit stärker als die übrigen, die über die Felder der westlichen Ebenen streift.]=],
		},
		{
			title = "In diesen Tagen",
			text = [=[Kein Bauer kann mit Gewissheit sagen, wie die Maschinen außer Kontrolle gerieten. Viele in {link:westfall}Westfall{/link} geben der {link:defias-brotherhood}Bruderschaft der Defias{/link} die Schuld, deren goblinische Verbündete in den Tiefen der {link:the-deadmines}Todesminen{/link} Golems bauen und befehligen. Der {link:gnomes}Gnom{/link} {link:ozwin-ironsprocket}Ozwin Ironsprocket{/link} hat ihre Teile untersucht und gelernt, sie außer Kraft zu setzen, wenn auch nur für einen Augenblick. Der Geist des Leuchtturms von Westfall nährt seine Flamme mit Öl, das aus ihren Gelenken abgelassen wurde. {link:farmer-saldean}Bauer Saldean{/link} will sie einfach loswerden.]=],
		},
	},
})
